import{_ as a,o as t,c as o,a2 as n}from"./chunks/framework.CPHNBVkq.js";const m=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md"}'),s={name:"guide/faq.md"};function r(i,e,h,l,c,d){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><p>Quick answers to common questions. If you don&#39;t find what you need here, check the relevant guide page or reach out to your administrator.</p><h2 id="my-pulse-feed-is-empty-why" tabindex="-1">My Pulse feed is empty. Why? <a class="header-anchor" href="#my-pulse-feed-is-empty-why" aria-label="Permalink to &quot;My Pulse feed is empty. Why?&quot;">​</a></h2><p>Most likely you haven&#39;t set up any channels yet — your feed only shows updates from channels you create. If you see <strong>&quot;No Channels Found,&quot;</strong> select <strong>Create Channel</strong> to add one. See <a href="./channels-create.html">Creating a Channel</a>.</p><p>If you have channels but see <strong>&quot;Could not find any Pulse Items,&quot;</strong> there&#39;s just nothing to show right now. Try a different channel, widen a channel&#39;s scope, or check back later. See <a href="./pulse-feed.html#when-the-feed-is-empty">When the feed is empty</a>.</p><h2 id="how-do-i-see-less-or-more-in-my-feed" tabindex="-1">How do I see less (or more) in my feed? <a class="header-anchor" href="#how-do-i-see-less-or-more-in-my-feed" aria-label="Permalink to &quot;How do I see less (or more) in my feed?&quot;">​</a></h2><p>Adjust your channels rather than the feed:</p><ul><li><strong>Too much?</strong> Add <strong>tags</strong> so the channel only includes updates about specific things, instead of the whole category. If it already has several tags, switch its scope to <strong>Narrow</strong> so updates must match <em>all</em> of them.</li><li><strong>Too little?</strong> Remove some tags so the channel covers more of its category. If it has several tags, switch its scope to <strong>Broad</strong> so matching <em>any one</em> of them is enough.</li></ul><p>See <a href="./channels-manage.html#tune-a-noisy-or-quiet-channel">Managing Channels</a>.</p><h2 id="what-s-the-difference-between-broad-and-narrow-scope" tabindex="-1">What&#39;s the difference between Broad and Narrow scope? <a class="header-anchor" href="#what-s-the-difference-between-broad-and-narrow-scope" aria-label="Permalink to &quot;What&#39;s the difference between Broad and Narrow scope?&quot;">​</a></h2><p>Scope decides how the tags you&#39;ve chosen are combined. <strong>Broad</strong> includes updates that match <strong>any one</strong> of your tags (a wider feed); <strong>Narrow</strong> includes only updates that match <strong>all</strong> of your tags at once (a tighter feed). With no tags — or a single tag — they behave the same. See <a href="./channels.html#how-scope-and-tags-work-together">How scope and tags work together</a>.</p><h2 id="why-are-no-tags-showing-when-i-create-a-channel" tabindex="-1">Why are no tags showing when I create a channel? <a class="header-anchor" href="#why-are-no-tags-showing-when-i-create-a-channel" aria-label="Permalink to &quot;Why are no tags showing when I create a channel?&quot;">​</a></h2><p>Tags come from the channel&#39;s <strong>category</strong>, so choose the category first. The available tags then reflect that category&#39;s data. See <a href="./channels.html#channel-tags">Channel Tags</a>.</p><h2 id="when-will-my-daily-summary-arrive" tabindex="-1">When will my Daily Summary arrive? <a class="header-anchor" href="#when-will-my-daily-summary-arrive" aria-label="Permalink to &quot;When will my Daily Summary arrive?&quot;">​</a></h2><p>At the hour you set under <strong>Settings → Notification Preferences</strong>, in the time zone shown there. See <a href="./notifications.html">Notifications &amp; Daily Summary</a>.</p><h2 id="my-daily-summary-time-looks-wrong-after-a-clock-change" tabindex="-1">My Daily Summary time looks wrong after a clock change. <a class="header-anchor" href="#my-daily-summary-time-looks-wrong-after-a-clock-change" aria-label="Permalink to &quot;My Daily Summary time looks wrong after a clock change.&quot;">​</a></h2><p>A daylight saving change can shift your usual time. Corbi shows a notice asking you to confirm — re-check the <strong>Daily Summary Time</strong> slider and it&#39;ll save again. See <a href="./notifications.html#time-zone">Daylight saving time</a>.</p><h2 id="what-s-the-difference-between-chat-and-tasks" tabindex="-1">What&#39;s the difference between Chat and Tasks? <a class="header-anchor" href="#what-s-the-difference-between-chat-and-tasks" aria-label="Permalink to &quot;What&#39;s the difference between Chat and Tasks?&quot;">​</a></h2><p>Use <a href="./chat.html"><strong>Chat</strong></a> for questions and back-and-forth conversations. Use <a href="./tasks.html"><strong>Tasks</strong></a> when you want Corbi to carry out something structured that you can review and keep.</p><h2 id="what-does-it-mean-that-a-task-is-draft-vs-live" tabindex="-1">What does it mean that a task is &quot;Draft&quot; vs. &quot;Live&quot;? <a class="header-anchor" href="#what-does-it-mean-that-a-task-is-draft-vs-live" aria-label="Permalink to &quot;What does it mean that a task is &quot;Draft&quot; vs. &quot;Live&quot;?&quot;">​</a></h2><p>A <strong>Draft</strong> is a proposed version you can review and refine; a <strong>Live</strong> version is the one currently active. You review the draft before it goes live. See <a href="./tasks.html#draft-and-live-versions">Draft and live versions</a>.</p><h2 id="i-don-t-see-chat-pulse-or-tasks-in-my-navigation" tabindex="-1">I don&#39;t see Chat, Pulse, or Tasks in my navigation. <a class="header-anchor" href="#i-don-t-see-chat-pulse-or-tasks-in-my-navigation" aria-label="Permalink to &quot;I don&#39;t see Chat, Pulse, or Tasks in my navigation.&quot;">​</a></h2><p>The areas you can use depend on your account&#39;s access. If something is missing, your organization may not have enabled it for you — check with your administrator.</p><h2 id="can-i-use-corbi-on-my-phone" tabindex="-1">Can I use Corbi on my phone? <a class="header-anchor" href="#can-i-use-corbi-on-my-phone" aria-label="Permalink to &quot;Can I use Corbi on my phone?&quot;">​</a></h2><p>Yes. Corbi is available as a mobile app in addition to the web app, and your channels and preferences are shared across both.</p>',25)])])}const f=a(s,[["render",r]]);export{m as __pageData,f as default};
